export default function search({ body }) {
  const email = String(body.email || "")
    .trim()
    .toLowerCase();
  if (!email || !body.submissionId || !body.transcript) throw Error("Missing client submission");
  return {
    email,
    filters: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
    transcript: String(body.transcript),
  };
}

