export default async function plan({ body, results, analysis, acknowledge, resolution }, ctx) {
  if (results.length > 1) throw Error("Multiple matching HubSpot contacts");
  const key = "feedback:" + body.submissionId + ":meeting",
    skip = { write: false, key, request: {} };
  if (!results.length) return skip;
  const contactId = String(results[0].id || ""),
    email = String(results[0].properties?.email || "")
      .trim()
      .toLowerCase();
  if (
    email !==
    String(body.email || "")
      .trim()
      .toLowerCase()
  )
    throw Error("Contact email mismatch");
  if (!/^\d+$/.test(contactId) || !analysis.summary) throw Error("Missing contact or summary");
  const old = await ctx.state.get(key);
  if (old?.status === "done") return skip;
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending HubSpot meeting " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return skip;
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    write: true,
    key,
    request: {
      engagement: { type: "MEETING" },
      metadata: { title: "New meeting", body: analysis.summary },
      associations: { contactIds: [contactId] },
    },
  };
}

