export default async function f({ key, statusCode, body }, ctx) {
  if (statusCode < 200 || statusCode >= 300 || !body?.engagement?.id)
    throw Error("Unknown meeting result");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

