export default async function plan(
  { body, analysis, product, administrative, support, commercial, acknowledge, resolution },
  ctx,
) {
  const map = { product, administrative, support, commercial },
    to = String(map[analysis.department] || "").trim();
  if (!to || to.startsWith("YOUR_")) throw Error("Configure recipient for " + analysis.department);
  const key = "feedback:" + body.submissionId + ":email",
    old = await ctx.state.get(key),
    text = "FROM CLIENT: " + body.email + "\n\n" + body.transcript,
    skip = { send: false, key, to, text };
  if (old?.status === "done") return skip;
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending department email " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return skip;
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { send: true, key, to, text };
}

